sign constraints","mekânsal planlama, erişilebilirlik ve tasarım kısıtları"],"chemical":["process design, mass balances and process safety","proses tasarımı, kütle dengesi ve proses güvenliği"],"mechatronics":["sensors, actuators, control loops and mechanical integration","sensörler, aktüatörler, kontrol döngüleri ve mekanik entegrasyon"],"dentist":["oral health, evidence and patient safety","ağız sağlığı, kanıt ve hasta güvenliği"],"physio":["functional assessment and rehabilitation safety","işlevsel değerlendirme ve rehabilitasyon güvenliği"],"dietitian":["nutrition evidence and individual variability","beslenme kanıtları ve bireysel farklılıklar"],"vet":["animal health, welfare and evidence","hayvan sağlığı, refahı ve kanıt"],"customer":["customer communication and issue resolution","müşteri iletişimi ve sorun çözme"],"writer":["narrative structure, factual accuracy and audience","anlatı yapısı, doğruluk ve hedef kitle"],"electrician":["electrical safety, measurements and troubleshooting","elektrik güvenliği, ölçümler ve arıza tespiti"],"chef":["food safety, preparation and quality","gıda güvenliği, hazırlık ve kalite"],"driver":["road safety, planning and vehicle checks","yol güvenliği, planlama ve araç kontrolleri"]};const domainLabels={"chip":"Chip Design / FPGA / ASIC","embedded":"Embedded / RTOS","edge":"Yapay Zekâ Mühendisi","dsp":"DSP / Real-time Audio","pcb":"PCB / EMC / Power","systems":"Bilgisayar Mühendisi","software":"Yazılım Mühendisi","data":"Veri Bilimci","cyber":"Siber Güvenlik Uzmanı","mechanical":"Makine Mühendisi","civil":"İnşaat Mühendisi","industrial":"Endüstri Mühendisi","energy":"Elektrik-Elektronik Mühendisi","it":"Bilgi Teknolojileri Uzmanı","medicine":"Doktor","nursing":"Hemşire","pharmacy":"Eczacı","psychology":"Psikolog","biotech":"Biyolog","research":"Akademisyen","math":"Matematikçi / İstatistikçi","finance":"Finans Uzmanı","accounting":"Muhasebe Uzmanı","law":"Avukat","risk":"Risk ve Uyum Uzmanı","management":"Yönetim Danışmanı","hr":"İnsan Kaynakları Uzmanı","sales":"Satış Uzmanı","marketing":"Pazarlama Uzmanı","logistics":"Lojistik Uzmanı","operations":"Proje Yöneticisi","education":"Öğretmen","translation":"Çevirmen","writing":"Editör","design":"Grafik / UX Tasarımcısı","media":"Gazeteci","creative":"Sanatçı","agriculture":"Ziraat Mühendisi","hospitality":"Turizm Uzmanı","trades":"Teknisyen","ai_eval":"Yapay Zekâ Eğitmeni ve Değerlendirme Uzmanı","custom":"Özel meslek / kendi alanım","architect":"Mimar","chemical":"Kimya Mühendisi","mechatronics":"Mekatronik Mühendisi","dentist":"Diş Hekimi","physio":"Fizyoterapist","dietitian":"Diyetisyen","vet":"Veteriner Hekim","customer":"Müşteri Temsilcisi","writer":"Yazar","electrician":"Elektrik Teknisyeni","chef":"Aşçı","driver":"Sürücü"};const kinds=["background","knowledge","case","evaluation","rubric","judgment","communication"];
const englishRoles={"chip":"Chip Design / FPGA / ASIC","embedded":"Embedded Systems / RTOS","edge":"AI Engineer","dsp":"Digital Signal Processing","pcb":"PCB Design / EMC / Power","systems":"Computer Engineer","software":"Software Engineer","data":"Data Scientist","cyber":"Cybersecurity Specialist","mechanical":"Mechanical Engineer","civil":"Civil Engineer","industrial":"Industrial Engineer","energy":"Electrical and Electronics Engineer","it":"IT Specialist","medicine":"Physician","nursing":"Nurse","pharmacy":"Pharmacist","psychology":"Psychologist","biotech":"Biologist","research":"Academic Researcher","math":"Mathematician or Statistician","finance":"Finance Specialist","accounting":"Accountant","law":"Lawyer","risk":"Risk and Compliance Specialist","management":"Management Consultant","hr":"HR Specialist","sales":"Sales Specialist","marketing":"Marketing Specialist","logistics":"Logistics Specialist","operations":"Project Manager","education":"Teacher","translation":"Translator","writing":"Editor","design":"Graphic or UX Designer","media":"Journalist","creative":"Artist","agriculture":"Agricultural Engineer","hospitality":"Tourism Specialist","trades":"Technician","ai_eval":"AI Trainer and Evaluation Specialist","custom":"Custom Profession","mixed":"Engineering","architect":"Architect","chemical":"Chemical Engineer","mechatronics":"Mechatronics Engineer","dentist":"Dentist","physio":"Physiotherapist","dietitian":"Dietitian","vet":"Veterinarian","customer":"Customer Service Representative","writer":"Writer","electrician":"Electrical Technician","chef":"Chef","driver":"Professional Driver"};
function roleQuestion(kind){const role=cfg.role||(cfg.lang==="en"?englishRoles[cfg.domain]:domainLabels[cfg.domain])||(cfg.lang==="en"?"Engineering":"Mühendislik");const topic=topics[cfg.domain]||(cfg.domain==="mixed"?["engineering design and verification","mühendislik tasarımı ve doğrulama"]:[role,role]);const t=topic[cfg.lang==="en"?0:1];const en=cfg.lang==="en";const detail=cfg.level==="advanced"?(en?" Include trade-offs, failure modes and validation.":" Ödünleşimleri, hata durumlarını ve doğrulamayı açıklayın."):cfg.level==="foundation"?(en?" Explain in simple terms.":" Basit terimlerle açıklayın."):"";const q={
background:en?["Describe your actual experience in "+role+". What tasks have you personally completed, and how did you verify quality?","Use a real example; distinguish your contribution from the team's."]:[""+role+" alanındaki gerçek deneyiminizi anlatın. Hangi görevleri bizzat tamamladınız ve kaliteyi nasıl doğruladınız?","Gerçek bir örnek kullanın; kendi katkınızı ekipten ayırın."],
experience:en?["Tell me about a real situation in "+role+" where you faced a difficult problem related to "+t+". What was your responsibility, what did you personally do, and what was the actual outcome? If you have not faced this, say so and describe a relevant learning project or a hypothetical approach.","STAR: Situation, Task, Action, Result. Use only actual facts; explain your contribution and evidence."]:[""+role+" alanında "+t+" ile ilgili karşılaştığınız gerçek bir zorluğu anlatın. Sorumluluğunuz neydi, bizzat ne yaptınız ve gerçek sonuç ne oldu? Böyle bir deneyiminiz yoksa belirtin; ilgili bir öğrenme projesi veya varsayımsal yaklaşım anlatın.","STAR: Durum, Görev, Eylem, Sonuç. Yalnız gerçek bilgileri ve kendi katkınızı kullanın."],
failure:en?["Describe a real mistake, setback or unexpected result in "+role+". How did you investigate it, respond and learn from it? If you have no such example, explain how you would handle a hypothetical setback.","Separate facts from assumptions; explain corrective action and what you learned."]:[""+role+" alanında yaşadığınız gerçek bir hata, aksaklık veya beklenmedik sonucu anlatın. Nasıl araştırdınız, ne yaptınız ve ne öğrendiniz? Böyle bir örneğiniz yoksa varsayımsal bir durumda nasıl ilerleyeceğinizi açıklayın.","Gerçekleri varsayımlardan ayırın; düzeltici eylemi ve öğrendiklerinizi belirtin."],
