rubric:en?["Create a scoring rubric for comparing two AI answers to a realistic "+role+" question about "+t+". What would make an answer unacceptable?","Define measurable criteria and examples of critical errors."]:[""+t+" konusunda gerçekçi bir "+role+" sorusuna verilen iki AI yanıtını karşılaştırmak için puanlama rubriği oluşturun. Hangi hatalar kabul edilemez?","Ölçülebilir kriterler ve kritik hata örnekleri."],
judgment:en?["In "+role+", when would you reject an AI-generated answer even if it sounds persuasive? Explain using "+t+" as an example."+detail,"Professional standards, evidence, limitations and escalation."]:[""+role+" alanında ikna edici görünse bile hangi durumda AI yanıtını reddedersiniz? "+t+" üzerinden açıklayın."+detail,"Mesleki standart, kanıt, sınırlar, gerektiğinde uzmana yönlendirme."],
communication:en?["Explain "+t+" to a non-specialist. Then describe how you would check that your explanation was understood.","Plain language, accurate analogy, check understanding."]:[""+t+" konusunu uzman olmayan birine açıklayın. Ardından açıklamanızın anlaşıldığını nasıl kontrol edeceğinizi anlatın.","Sade dil, doğru benzetme, anlayışı kontrol etme."]};return {text:q[kind][0],hint:q[kind][1],kind};}
function chooseUniversal(){const seq=cfg.format==="evaluation"?["evaluation","rubric","judgment","case","communication"]:cfg.format==="behavioral"?["background","case","judgment","communication","rubric"]:cfg.format==="technical"?["knowledge","case","judgment","communication","evaluation"]:["background","knowledge",Math.random()<0.5?"experience":"failure","evaluation","rubric","case","judgment","communication"];let kind=seq.find(x=>!used.has("kind:"+x)&&(!["experience","failure"].includes(x)||!used.has("kind:experienceSlot")))||seq[history.length%seq.length];used.add("kind:"+kind);if(["experience","failure"].includes(kind))used.add("kind:experienceSlot");return roleQuestion(kind);}
const error=t=>$("error").textContent=t;const setState=t=>$("state").textContent=t;
let documentPlan=[];function selectQuestion(){if(documentPlan.length){const q=documentPlan.shift();return q;}const kindCount=used.has("kind:background")&&!used.has("kind:knowledge");if(kindCount&&["energy","systems","edge"].includes(cfg.domain)){const keys=cfg.domain==="energy"?["chip","pcb","embedded","dsp"]:cfg.domain==="systems"?["systems","embedded","chip"]:["edge"];const pool=keys.flatMap(k=>bank[k]||[]);const eligible=cfg.level==="foundation"?keys.flatMap(k=>(bank[k]||[]).slice(0,2)):cfg.level==="advanced"?keys.flatMap(k=>(bank[k]||[]).slice(2)):pool;const q=eligible[Math.floor(Math.random()*eligible.length)];if(q){used.add("kind:knowledge");return {text:q[cfg.lang==="en"?0:1],hint:q[2],kind:"knowledge"};}}if(cfg.format!=="technical"||(!bank[cfg.domain]&&cfg.domain!=="mixed")||cfg.role)return chooseUniversal();const groups=cfg.domain==="mixed"?Object.values(bank):[bank[cfg.domain]];let pool=groups.flatMap(a=>cfg.level==="foundation"?a.slice(0,2):cfg.level==="advanced"?a.slice(2):a.slice(1,3));let available=pool.filter(x=>!used.has(x[0]));if(!available.length)available=pool;const q=available[Math.floor(Math.random()*available.length)];used.add(q[0]);return {text:q[cfg.lang==="en"?0:1],hint:q[2]};}
function unlock(on){window.CueContext.lock(on);for(const id of ["domain","level","language","style","limit","code","consent"])$(id).disabled=on;$("begin").disabled=on;$("finish").disabled=!on;window.CueContext.syncGate();}
function controls(){const ready=!!cfg&&!finished&&!busy&&!rec&&!!current&&$("feedback").classList.contains("hidden");$("speak").disabled=!ready;$("hint").disabled=!ready||cfg.style==="exam";$("answer").disabled=!ready;$("record").disabled=!ready;$("recordStop").disabled=!rec;$("evaluate").disabled=!ready||!$("answer").value.trim()||history.length>=5||(needsTranscriptCheck&&!$("transcriptConfirmed").checked);$("nextBank").disabled=busy||history.length>=5||finished;$("next").disabled=busy||history.length>=5||finished;$("retry").disabled=busy||history.length>=5;}
function tick(){const s=Math.max(0,Math.ceil((deadline-Date.now())/1000));$("time").textContent=String(Math.floor(s/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0");$("progress").style.width=(100*s/cfg.limit)+"%";$("elapsed").textContent=Math.round((Date.now()-started)/1000)+" sn";if(!s&&rec?.state==="recording")rec.stop();if(!s&&!busy&&$("feedback").classList.contains("hidden"))setState("SÜRE DOLDU · CEVABI DEĞERLENDİR");}
let originalTranscript="";function transcriptDiff(original,edited){const tokenize=s=>String(s).normalize("NFKC").toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu)||[];const a=tokenize(original),b=tokenize(edited);if(!a.length)return null;if(a.length>1200||b.length>1200)return null;let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(prev[j]+1,row[j-1]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=row;}return {edits:prev[b.length],words:a.length};}function load(q){originalTranscript="";$("transcriptEdits").textContent="";needsTranscriptCheck=false;$("transcriptConfirmed").checked=false;$("transcriptCheck").classList.add("hidden");$("audioMetrics").textContent="";current=q;follow="";$("question").textContent=q.text;$("qmeta").textContent=(cfg.role||domainLabels[cfg.domain]||cfg.domain)+" · "+({foundation:"BAŞLANGIÇ",intermediate:"ORTA",advanced:"İLERİ"}[cfg.level]||"PROVA")+" · "+({technical:"TEKNİK",knowledge:"BİLGİ",background:"DENEYİM",experience:"DENEYİM",behavioral:"DAVRANIŞSAL",expert:"UZMANLIK",case:"VAKA",evaluation:"DEĞERLENDİRME",followup:"TAKİP"}[q.kind||cfg.format]||"MESLEKİ PROVA");$("answer").value="";$("hintText").classList.add("hidden");$("feedback").classList.add("hidden");error("");setState("CEVABINI VER");deadline=Date.now()+cfg.limit*1000;clearInterval(timer);timer=setInterval(tick,250);tick();controls();}
$("begin").onclick=async()=>{if(!$("code").value||!$("consent").checked)return error("Erişim kodu ve onay gerekli.");if($("domain").value==="custom"&&!$("customRole").value.trim())return error("Mesleğini yaz.");const docError=window.CueContext.validate();if(docError)return error(docError);const docs=window.CueContext.payload();cfg={docs,domain:$("domain").value,role:$("domain").value==="custom"?$("customRole").value.trim():"",format:"expert",level:$("level").value,lang:$("language").value,style:$("style").value,limit:+$("limit").value,code:$("code").value};finished=false;history=[];used.clear();documentPlan=[];started=Date.now();const n=++epoch;unlock(true);summary();if(docs.jobDescription||docs.cvText){busy=true;current=null;controls();setState("BELGELER ANALİZ EDİLİYOR");try{const x=await post({action:"plan",domain:cfg.domain,role:cfg.role,level:cfg.level,language:cfg.lang,consent:true,...docs});if(n!==epoch||finished)return;documentPlan=x.questions;if(!Array.isArray(documentPlan)||!documentPlan.length)throw Error("Kişiselleştirilmiş soru planı alınamadı.");$("contextState").textContent="Belge analizi tamamlandı.";}catch(e){if(n!==epoch||finished)return;busy=false;finish();error("Belge analizi başarısız: "+e.message+" Belgeleri temizleyerek genel prova yapabilirsin.");return;}finally{if(n===epoch)busy=false;}}if(n===epoch&&!finished)load(selectQuestion());};
$("answer").oninput=()=>{if(needsTranscriptCheck){$("transcriptConfirmed").checked=false;$("transcriptEdits").textContent="";}controls();};$("transcriptConfirmed").onchange=()=>{if(needsTranscriptCheck&&$("transcriptConfirmed").checked){const d=transcriptDiff(originalTranscript,$("answer").value);$("transcriptEdits").textContent=d?d.edits+" kelime düzeyi değişiklik / "+d.words+" ilk döküm kelimesi. Bu, kullanıcı düzeltmesi ölçümüdür; bağımsız ses doğruluğu değildir.":"Düzeltme ölçümü hesaplanamadı.";}else $("transcriptEdits").textContent="";controls();};$("hint").onclick=()=>{$("hintText").textContent=current.hint||"Varsayımları belirt, yöntemini açıkla ve doğrulama öner."; $("hintText").classList.remove("hidden");};
