files.studio.css:
/* CueBuddy unified screen design; print template stays independent. */
:root{color-scheme:dark;--surface:#141c2d;--line:#354059;--muted:#c5d0e2;--accent:#a99aef;--primary:#7456e8;--field:#101727;--radius:14px}
body{font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:radial-gradient(ellipse at 84% 0%,#201c39 0,transparent 45%),#0b101d;color:#edf1ff}
body:not(.reader-mode)>main{max-width:1320px;width:100%;padding:20px 24px;margin:auto}
[hidden]{display:none!important}
.studio-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 0 13px;margin:0;border-bottom:1px solid var(--line);flex-wrap:wrap}
.studio-brand{display:flex;align-items:center;gap:10px;line-height:1.15;text-decoration:none;color:#f4f5ff;padding:0;border:0;font-size:19px;font-weight:700;white-space:nowrap}
.studio-brand .brand-title,.studio-brand .brand-subtitle{display:block}.studio-brand b{font-size:11px;letter-spacing:.07em;color:#c7b9ff}.studio-brand small{font-size:9px;color:var(--muted);margin-top:5px;letter-spacing:0;white-space:normal}
.brand-mark{width:39px;height:39px;border-radius:11px;background:var(--primary);display:grid;place-items:center;flex:none;font-size:23px;color:#fff}
.studio-tabs{display:flex;gap:4px;align-items:center;background:#111725;border:1px solid var(--line);padding:4px;border-radius:10px;flex-wrap:wrap}.studio-tabs a{display:grid;place-items:center;min-height:44px;padding:8px 14px;border:0;border-radius:7px;color:var(--muted);font-weight:650;font-size:13px;white-space:nowrap;text-decoration:none}.studio-tabs a[aria-current=page]{background:#302953;color:#ece6ff}.version-label{font-size:11px;color:var(--muted);white-space:nowrap}
.studio-intro{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:19px 0 15px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:.12em;color:var(--accent)}.studio-intro h1{font-size:clamp(24px,3vw,34px);line-height:1.15;letter-spacing:-.03em;margin:4px 0 5px}.studio-intro p{font-size:13px;margin:0;color:var(--muted)}.private-label{display:flex;align-items:center;gap:6px;white-space:nowrap;color:var(--muted);font-size:11px}.private-label span{height:7px;width:7px;border-radius:50%;background:#83d7b1}
.studio-footer{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:11px;border-top:1px solid var(--line);margin-top:16px;padding:12px 0}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:17px;min-width:0}.panel h2:not(.cv-band){font-size:16px;margin:0 0 12px}.panel :is(input:not([type=checkbox]),select,textarea,button){font:inherit;border-radius:9px}.panel .primary{background:var(--primary);color:#fff;border:0;font-weight:700}.panel :is(input,select,textarea,button,summary):focus-visible,.studio-tabs a:focus-visible,.studio-brand:focus-visible{outline:3px solid #c6b7ff;outline-offset:3px}
.script-workspace{display:grid;grid-template-columns:minmax(0,1.8fr) minmax(240px,1fr);gap:14px;align-items:start}.script-editor textarea{display:block;width:100%;min-height:220px;background:var(--field);font-size:16px}.script-editor label{color:var(--muted);font-size:12px}.script-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-top:10px}.script-actions button{min-height:44px}.script-guide p{font-size:13px}.guide-item{display:flex;align-items:center;justify-content:space-between;gap:12px;border-top:1px solid var(--line);padding:10px 0}.guide-item span{font-weight:650}.guide-item small{color:var(--muted);text-align:right}
.cv-empty{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:10px;min-height:220px;padding:20px;text-align:center;background:var(--field);border:1px dashed var(--line);border-radius:12px;color:var(--accent)}.cv-empty strong{color:#edf1ff}.cv-empty p{font-size:13px;max-width:350px;color:var(--muted);margin:0}
@media(max-width:1050px){.studio-header{gap:10px}.studio-tabs{order:3;width:100%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr))}.studio-tabs a{min-width:0}}
@media(max-width:900px){body:not(.reader-mode)>main{padding:14px}.grid,.workspace,.script-workspace{grid-template-columns:minmax(0,1fr)}.studio-intro{align-items:flex-start}.private-label{white-space:normal;text-align:right}}
@media(max-width:460px){body:not(.reader-mode)>main{padding:10px}.studio-tabs a{padding:5px 3px;font-size:11px;white-space:normal;text-align:center;line-height:1.25;overflow-wrap:anywhere}.brand-mark{width:34px;height:34px}.studio-brand{font-size:17px}.studio-brand small{font-size:8px}.version-label{font-size:10px}.studio-intro{display:block}.private-label{margin-top:8px}.panel{padding:12px}.script-actions button{width:100%}.studio-footer{font-size:10px}.script-editor textarea{min-height:160px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}

/* RC12: readable inactive controls; screen-only palette. */
:root{--disabled-text:#b8c5d9;--disabled-bg:#252b42;--disabled-primary:#302952;--disabled-border:#48536d}
body button:disabled,body .panel button:disabled,body .context-panel button:disabled,body #stage button:disabled{opacity:1;color:var(--disabled-text);background:var(--disabled-bg);border:1px solid var(--disabled-border);cursor:not-allowed;box-shadow:none}
body button.primary:disabled,body .panel .primary:disabled{background:var(--disabled-primary);color:var(--disabled-text);border:1px solid #52466f}
.studio-intro p,.panel small,.panel .note,.panel .context-note,.panel .practice-note,.panel .session-note p,.script-guide p,.guide-item small,.cv-empty p,.reader-tools label,.technical-details{color:var(--muted)}

/* RC13 mobile reflow: constrain intrinsic widths, not the viewport. */
html,body{width:100%;min-width:0;margin:0}
body:not(.reader-mode)>main{box-sizing:border-box;min-width:0;max-inline-size:min(1320px,100%)}
.studio-header,.studio-tabs,.studio-intro,.studio-footer,.grid,.workspace,.script-workspace,.panel,.field-grid,.doc-grid,.context-panel,.context-field,.context-row,.action-row{min-width:0;max-width:100%;box-sizing:border-box}
.studio-brand,.studio-brand>span:last-child,.studio-intro>div,.studio-footer>span{min-width:0;max-width:100%;overflow-wrap:anywhere}
.studio-brand{white-space:normal}
.studio-tabs a{min-width:0;max-width:100%;box-sizing:border-box}
.panel :is(input:not([type=checkbox]),select,textarea,button),.context-panel input[type=file]{min-width:0;max-width:100%;box-sizing:border-box}
.field-grid>* ,.doc-grid>* ,.action-row>* ,.grid>* ,.workspace>* ,.script-workspace>* ,.row>*{min-width:0}
.context-panel,.context-row,.context-field, .session-note,.setup-guide,.studio-intro p,.studio-footer,.private-label{overflow-wrap:anywhere}
.context-panel label,.check,.context-consent{overflow-wrap:anywhere}
.context-panel input[type=file]{width:100%}
@media(max-width:950px){
body:not(.reader-mode)>main{width:100%;max-width:100%;padding:14px}
body:not(.reader-mode) .grid,body:not(.reader-mode) .grid.practice-workspace,.workspace,.script-workspace{grid-template-columns:minmax(0,1fr)!important}
.studio-header{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}
.studio-tabs{grid-column:1/-1;grid-row:2;order:0;width:100%;max-width:100%;grid-template-columns:repeat(4,minmax(0,1fr))}
.studio-tabs a{white-space:normal;overflow-wrap:anywhere;text-align:center}
.version-label{grid-column:2;grid-row:1;font-size:10px}
}
@media(max-width:600px){
body:not(.reader-mode)>main{padding:12px max(10px,env(safe-area-inset-right)) 12px max(10px,env(safe-area-inset-left))}
.studio-tabs{grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;padding:4px}
.studio-tabs a{font-size:13px;min-height:44px;padding:7px 5px;line-height:1.3;display:grid;place-items:center;white-space:normal}
.studio-brand{font-size:17px;gap:7px}.studio-brand small{font-size:8px;white-space:normal;line-height:1.3}
.studio-brand .brand-mark{width:34px;height:34px}
.studio-intro{display:block;margin:16px 0 12px}.studio-intro h1{font-size:24px;overflow-wrap:anywhere}.studio-intro p{font-size:13px;line-height:1.5}.private-label{margin-top:8px;white-space:normal;text-align:left}
.panel{padding:12px}
body .field-grid,body .doc-grid,body .action-row{grid-template-columns:minmax(0,1fr)!important}
body .action-row button{width:100%;min-width:0;min-height:44px}
body .panel :is(input:not([type=checkbox]):not([type=file]),select,textarea){font-size:16px;min-height:44px}
body .panel button{min-height:44px}
body .panel .context-row button{min-height:44px}
.context-row,.reader-tools,.reader-nav,.status,.row{flex-wrap:wrap;max-width:100%}
