body .practice-workspace .row>*{flex:1 1 100%;min-width:0}
body .reader-tools select{min-width:0;max-width:100%}
body .reader-mode .reading-panel{width:100%;max-width:100%}
.paper-shell,.preview-frame{min-width:0;max-width:100%}
