}
@media(max-width:360px){.studio-header{grid-template-columns:minmax(0,1fr)}.version-label{grid-column:1;grid-row:2}.studio-tabs{grid-row:3}.studio-intro h1{font-size:22px}body .practice-workspace .scores{grid-template-columns:minmax(0,1fr)}}

