.session-active .mobile-setup-link{display:none}

/* Public legal links; no additional tracking or storage. */
.legal-links{display:flex;flex-wrap:wrap;gap:6px 14px;flex:1 1 100%;font-size:12px}.legal-links a,.legal-inline a{color:#c7b9ff;text-decoration:underline;text-underline-offset:2px}.legal-inline{font-size:12px;line-height:1.5;margin:7px 0}.legal-links a:focus-visible,.legal-inline a:focus-visible{outline:2px solid #c6b7ff;outline-offset:3px}
